CREATE TABLE IF NOT EXISTS admins(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings(`key` VARCHAR(100) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS cities(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,province VARCHAR(120) NOT NULL,name VARCHAR(120) NOT NULL,UNIQUE KEY city_unique(province,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctors(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(190) NOT NULL,specialty VARCHAR(190) NOT NULL,city_id INT UNSIGNED NOT NULL,clinic_address TEXT NOT NULL,subscription_until DATE DEFAULT NULL,active TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(city_id) REFERENCES cities(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS slots(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,starts_at DATETIME NOT NULL,capacity INT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY unique_slot(doctor_id,starts_at),FOREIGN KEY(doctor_id) REFERENCES doctors(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS bookings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slot_id BIGINT UNSIGNED NOT NULL,patient_name VARCHAR(190) NOT NULL,phone VARCHAR(20) NOT NULL,tracking_code VARCHAR(32) NOT NULL UNIQUE,status ENUM('confirmed','cancelled') NOT NULL DEFAULT 'confirmed',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_slot_status(slot_id,status),FOREIGN KEY(slot_id) REFERENCES slots(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,booking_id BIGINT UNSIGNED NULL,amount INT UNSIGNED NOT NULL,status VARCHAR(30) NOT NULL,reference VARCHAR(190) NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(booking_id) REFERENCES bookings(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,starts_on DATE NOT NULL,ends_on DATE NOT NULL,amount INT UNSIGNED NOT NULL DEFAULT 0,payment_status VARCHAR(30) NOT NULL DEFAULT 'manual',FOREIGN KEY(doctor_id) REFERENCES doctors(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
